<?php
namespace Tests\Feature;
use Tests\TestCase;
use App\Models\{User,Hazard,HazardType};
use App\Services\{ConditionFeedService,MapConditionService,ConditionIconService};
use Illuminate\Foundation\Testing\DatabaseTransactions;
use Illuminate\Support\Facades\Storage;
use Illuminate\Http\UploadedFile;
class AdminConditionTypeTest extends TestCase {
 use DatabaseTransactions;
 protected function setUp():void {if(getenv('RUTEAMAN_SPATIAL_TESTS')!=='1')$this->markTestSkipped('Dedicated spatial database required.');parent::setUp();$this->seed(\Database\Seeders\DemoSeeder::class);Storage::fake('local');}
 private function owner(bool $reauth=true):User{$u=(new User)->forceFill(['display_name'=>'Owner test','email'=>'type-owner@test.invalid','password'=>'FixturePassword123!','active'=>true,'status'=>'active','role'=>'owner','permissions'=>[]]);$u->save();$this->actingAs($u);if($reauth)$this->withSession(['admin.reauth_at'=>time(),'admin.last_seen'=>time()]);return $u;}
 private function data(array $changes=[]):array{return [...['label'=>'Longsor','code'=>'longsor','icon_mode'=>'preset','icon_key'=>'warning','severity_weight'=>3,'ttl_minutes'=>720,'rain_sensitive'=>1,'night_only'=>0],...$changes];}
 public function test_owner_only_management_and_reauthentication():void{$this->get('/admin/condition-types')->assertRedirect(route('login'));$this->actingAs(User::where('email','admin_a@ruteaman.test')->firstOrFail())->get('/admin/condition-types')->assertForbidden();$this->postJson(route('admin.condition-types.store'),$this->data())->assertForbidden();$this->owner(false);$this->get('/admin/condition-types')->assertOk()->assertSee('Jenis Kondisi');$this->postJson(route('admin.condition-types.store'),$this->data())->assertStatus(428);}
 public function test_new_category_presets_available_on_reports_and_public_catalog():void{$this->owner();$this->post(route('admin.condition-types.store'),$this->data(['code'=>'','icon_key'=>'obstruction']))->assertRedirect(route('admin.condition-types'));$t=HazardType::where('code','longsor')->firstOrFail();$this->assertSame('obstruction',$t->icon_key);$this->assertSame(3,$t->severity_weight);$this->assertTrue($t->rain_sensitive);auth()->logout();$this->get(route('guest-reports.create'))->assertOk()->assertSee('Longsor')->assertSee('name="type_id" value="'.$t->id.'"',false);$this->assertContains('longsor',array_column(app(ConditionIconService::class)->catalog(),'code'));$this->assertDatabaseHas('audit_logs',['action'=>'condition-type.create','entity_id'=>$t->id]);}
 public function test_invalid_values_and_duplicate_codes_rejected():void{$this->owner();$this->post(route('admin.condition-types.store'),$this->data(['code'=>'flood']))->assertSessionHasErrors('code');foreach([['code'=>'BAD CODE'],['label'=>'<script>'],['icon_key'=>'<svg onload=alert(1)>'],['severity_weight'=>0],['ttl_minutes'=>0],['icon_mode'=>'remote']] as $changes)$this->post(route('admin.condition-types.store'),$this->data($changes))->assertSessionHasErrors();$this->assertDatabaseMissing('hazard_types',['code'=>'longsor']);}
 public function test_logo_is_reencoded_and_public_route_has_no_private_metadata():void{$this->owner();$this->post(route('admin.condition-types.store'),$this->data(['icon_mode'=>'upload','icon'=>UploadedFile::fake()->image('logo.png',160,80)]))->assertRedirect();$t=HazardType::where('code','longsor')->firstOrFail();$this->assertTrue(Storage::disk('local')->exists($t->icon_path));$this->assertStringNotContainsString('logo.png',$t->icon_path);$size=getimagesize(Storage::disk('local')->path($t->icon_path));$this->assertSame(256,$size[0]);$this->assertSame(256,$size[1]);$this->assertSame('image/webp',$size['mime']);$v=app(ConditionIconService::class)->visual($t);$this->assertStringContainsString('/media/condition-types/'.$t->id,$v['icon_url']);$this->assertArrayNotHasKey('icon_path',$t->toArray());auth()->logout();$this->get($v['icon_url'])->assertOk()->assertHeader('Content-Type','image/webp')->assertHeader('Cache-Control','no-store, private');}
 public function test_upload_missing_svg_and_oversized_rejected():void{$this->owner();$this->post(route('admin.condition-types.store'),$this->data(['icon_mode'=>'upload']))->assertSessionHasErrors('icon');$this->post(route('admin.condition-types.store'),$this->data(['icon_mode'=>'upload','icon'=>UploadedFile::fake()->create('unsafe.svg',2,'image/svg+xml')]))->assertSessionHasErrors('icon');$this->post(route('admin.condition-types.store'),$this->data(['icon_mode'=>'upload','icon'=>UploadedFile::fake()->image('big.png',1200,1000)]))->assertSessionHasErrors('icon');$this->assertCount(0,Storage::disk('local')->allFiles('condition-icons'));}
 public function test_logo_preserved_replaced_and_switch_to_preset_removes_old_file():void{$this->owner();$this->post(route('admin.condition-types.store'),$this->data(['icon_mode'=>'upload','icon'=>UploadedFile::fake()->image('logo.png')]))->assertRedirect();$t=HazardType::where('code','longsor')->firstOrFail();$old=$t->icon_path;$v1=app(ConditionIconService::class)->visual($t)['icon_url'];$this->patch(route('admin.condition-types.update',$t),$this->data(['icon_mode'=>'upload','label'=>'Longsor tanah','code'=>'changed']))->assertRedirect();$this->assertSame($old,$t->fresh()->icon_path);$this->assertSame('longsor',$t->fresh()->code);$this->patch(route('admin.condition-types.update',$t),$this->data(['icon_mode'=>'upload','icon'=>UploadedFile::fake()->image('new.webp')]))->assertRedirect();$this->assertFalse(Storage::disk('local')->exists($old));$this->assertNotSame($v1,app(ConditionIconService::class)->visual($t->fresh())['icon_url']);$new=$t->fresh()->icon_path;$this->patch(route('admin.condition-types.update',$t),$this->data(['icon_key'=>'road_closed']))->assertRedirect();$this->assertNull($t->fresh()->icon_path);$this->assertFalse(Storage::disk('local')->exists($new));$this->get(route('condition-types.icon',$t))->assertNotFound();}
 public function test_existing_reports_keep_type_id_and_use_new_icon_metadata():void{$this->owner();$h=Hazard::where('public_slug','demo-lubang-jl-mawar')->firstOrFail();$id=$h->type_id;$this->patch(route('admin.condition-types.update',$h->type),$this->data(['label'=>'Jalan rusak baru','icon_key'=>'road_damage']))->assertRedirect();$h->refresh()->load('type');$this->assertSame($id,$h->type_id);foreach([app(ConditionFeedService::class)->item($h),app(MapConditionService::class)->item($h)] as $item){$this->assertSame('Jalan rusak baru',$item['type_label']);$this->assertSame('road_damage',$item['type_visual']['icon_key']);$this->assertArrayNotHasKey('icon_path',$item['type_visual']);}$this->assertGreaterThan(0,$h->reports()->count());}
 public function test_header_account_trigger_has_icon_only_but_accessible_name():void{$res=$this->get('/')->assertOk();preg_match('/<button type="button" class="account-header-trigger".*?<\/button>/s',$res->getContent(),$m);$this->assertNotEmpty($m);$this->assertStringContainsString('aria-label="Buka menu akun"',$m[0]);$this->assertStringNotContainsString('<span>Akun</span>',$m[0]);$this->assertStringContainsString('<svg',$m[0]);}
}
